#pragma once
// Movement geometry for this watch, generated by tools/make_art.py so the
// C side agrees with the art. Lengths are in 1/16 px ("x16").
#include <pebble.h>

typedef struct {
  int16_t cx16, cy16;  // arbor
  uint8_t sheet;       // its rim sheet in the art blob
  uint8_t teeth;
  uint8_t frames;      // rim frames per tooth
  int8_t dir;          // 1 clockwise, -1 anticlockwise
  uint8_t drive;       // 0 the going train, 1 the escapement
  uint8_t phase;       // starting angle, 1/256 tooth (meshing wheels interlock)
  uint8_t spokes;      // 0 = none drawn
  int16_t r_hub16;     // spokes run from here...
  int16_t r_in16;      // ...to just under the rim
  int16_t w_hub16;     // spoke width at the hub
  int16_t w_rim16;     // and at the rim
} GearSpec;

#include "layout_gen.h"
